const MODEL_GENERATED_MARKER: &str = "// @generated by rozectl. DO NOT EDIT.";
const MODEL_ORM_MARKER_PREFIX: &str = "// @roze-model-orm: ";
const MAX_GROUPED_AGGREGATE_PAIRS: usize = 8;
const MAX_PAIRWISE_GROUP_COUNT_HELPERS: usize = 8;

/// Compatibility version for the programmatic model generator extension API.
/// Increment only when an extension must change its implementation to compile
/// or preserve its previous behavior.
pub const MODEL_GENERATOR_EXTENSION_API_VERSION: u32 = 1;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ModelFormat {
    Auto,
    Ent,
    Dsl,
    Sql,
    Mongo,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ModelOrm {
    SeaOrm,
    Toasty,
}

impl ModelOrm {
    fn marker_name(self) -> &'static str {
        match self {
            Self::SeaOrm => "sea-orm",
            Self::Toasty => "toasty",
        }
    }
}

pub fn resolve_model_orm(
    out: &Path,
    mode: GenerateMode,
    requested: Option<ModelOrm>,
    switch_orm: bool,
) -> anyhow::Result<ModelOrm> {
    if switch_orm {
        anyhow::ensure!(
            mode == GenerateMode::Update && requested.is_some(),
            "switch_orm requires update mode and an explicit target ORM"
        );
    }
    if mode != GenerateMode::Update {
        return Ok(requested.unwrap_or(ModelOrm::SeaOrm));
    }

    let existing = detect_existing_model_orm(out)?;
    match (existing, requested) {
        (Some(existing), None) => Ok(existing),
        (Some(existing), Some(requested)) if existing == requested => Ok(existing),
        (Some(_), Some(requested)) if switch_orm => Ok(requested),
        (Some(existing), Some(requested)) => bail!(
            "model project uses `{}` but `--orm {}` was requested; add `--switch-orm` to confirm the generated ORM migration",
            existing.marker_name(),
            requested.marker_name()
        ),
        (None, Some(requested)) => Ok(requested),
        (None, None) => bail!(
            "cannot determine the existing model ORM for `--update`; pass `--orm sea-orm` or `--orm toasty` explicitly"
        ),
    }
}

fn detect_existing_model_orm(out: &Path) -> anyhow::Result<Option<ModelOrm>> {
    let model_mod = out.join("src/model/mod.rs");
    if model_mod.is_file() {
        let content = fs::read_to_string(&model_mod)
            .with_context(|| format!("failed to read {}", model_mod.display()))?;
        if let Some(marker) = content
            .lines()
            .find_map(|line| line.strip_prefix(MODEL_ORM_MARKER_PREFIX))
        {
            return match marker.trim() {
                "sea-orm" => Ok(Some(ModelOrm::SeaOrm)),
                "toasty" => Ok(Some(ModelOrm::Toasty)),
                value => bail!(
                    "unsupported model ORM marker `{value}` in {}",
                    model_mod.display()
                ),
            };
        }
    }

    let manifest_path = out.join("Cargo.toml");
    if !manifest_path.is_file() {
        return Ok(None);
    }
    let manifest = fs::read_to_string(&manifest_path)
        .with_context(|| format!("failed to read {}", manifest_path.display()))?;
    let document = manifest
        .parse::<toml_edit::DocumentMut>()
        .with_context(|| format!("failed to parse {}", manifest_path.display()))?;
    let dependencies = document
        .get("dependencies")
        .and_then(toml_edit::Item::as_table);
    let has_sea_orm = dependencies.is_some_and(|deps| deps.contains_key("sea-orm"));
    let has_toasty = dependencies.is_some_and(|deps| deps.contains_key("toasty"));
    match (has_sea_orm, has_toasty) {
        (true, false) => Ok(Some(ModelOrm::SeaOrm)),
        (false, true) => Ok(Some(ModelOrm::Toasty)),
        _ => Ok(None),
    }
}

