#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ExtensionFileOwnership {
    /// Extension-owned generated output, refreshed on every generation.
    Generated,
    /// Application-owned output, created once and preserved by `--update`.
    Application,
}

#[derive(Debug, Clone)]
pub struct ModelExtensionFile {
    pub relative_path: std::path::PathBuf,
    pub contents: String,
    pub ownership: ExtensionFileOwnership,
}

/// Stable model-codegen extension surface. Extensions may validate or enrich
/// the schema graph before built-in rendering and may emit additional files
/// afterwards. Registration order is deterministic.
pub trait ModelGeneratorExtension: Send + Sync {
    fn name(&self) -> &'static str;

    fn transform(&self, _graph: &mut ModelGenerationGraph) -> anyhow::Result<()> {
        Ok(())
    }

    fn generate(&self, _graph: &ModelGenerationGraph) -> anyhow::Result<Vec<ModelExtensionFile>> {
        Ok(Vec::new())
    }
}

