fn normalized_source_kind(format: ModelFormat, source: &str) -> ModelFormat {
    match format {
        ModelFormat::Auto if looks_like_sql(source) => ModelFormat::Sql,
        ModelFormat::Auto if looks_like_ent(source) => ModelFormat::Ent,
        ModelFormat::Auto => ModelFormat::Dsl,
        other => other,
    }
}

/// Normalize `.ent`, legacy model DSL, or SQL DDL into canonical `.ent`.
pub fn normalize_model_source_to_ent(source: &str, format: ModelFormat) -> anyhow::Result<String> {
    match normalized_source_kind(format, source) {
        ModelFormat::Ent => Ok(source.to_string()),
        ModelFormat::Sql => Ok(render_ent_schema(&parse_sql_models(source)?)),
        ModelFormat::Dsl | ModelFormat::Mongo => Ok(render_ent_schema(&parse_dsl_models(source)?)),
        ModelFormat::Auto => unreachable!("auto model format is normalized above"),
    }
}

fn render_ent_schema(models: &[ModelSpec]) -> String {
    use std::fmt::Write as _;

    let mut out =
        String::from("// @generated by rozectl. Edit this file, then regenerate model code.\n\n");
    for model in models {
        writeln!(out, "entity {} {{", to_pascal_case(&model.name)).unwrap();
        writeln!(out, "  table {}", quote_ent_string(&model.table)).unwrap();
        if let Some(schema_name) = &model.schema_name {
            writeln!(out, "  schema {}", quote_ent_string(schema_name)).unwrap();
        }
        if model.cache {
            writeln!(out, "  cache true").unwrap();
        }
        if let Some(cache_ttl_secs) = model.cache_ttl_secs {
            writeln!(out, "  cache_ttl_secs {cache_ttl_secs}").unwrap();
        }
        if let Some(negative_cache_ttl_secs) = model.negative_cache_ttl_secs {
            writeln!(out, "  negative_cache_ttl_secs {negative_cache_ttl_secs}").unwrap();
        }
        if !model.cache_keys.is_empty() {
            writeln!(out, "  cache_key {}", model.cache_keys.join(", ")).unwrap();
        }
        if let Some(cache_prefix) = &model.cache_prefix {
            writeln!(out, "  cache_prefix {}", quote_ent_string(cache_prefix)).unwrap();
        }
        if let Some(tenant) = &model.tenant {
            writeln!(out, "  tenant {tenant}").unwrap();
        }
        if let Some(soft_delete) = &model.soft_delete {
            writeln!(out, "  soft_delete {soft_delete}").unwrap();
        }
        render_ent_annotations(&mut out, "  ", &model.annotations);
        writeln!(out).unwrap();

        for field in &model.fields {
            if model
                .edges
                .iter()
                .any(|edge| edge.implicit_field && edge.field == field.name)
            {
                continue;
            }
            let field_unique = model.indexes.iter().any(|index| {
                index.annotations.is_empty() && is_default_field_unique_index(index, &field.name)
            });
            let field_indexed = model.indexes.iter().any(|index| {
                index.annotations.is_empty() && is_default_field_index(index, &field.name)
            });
            writeln!(
                out,
                "  field {}: {} {{",
                field.name,
                rust_type_to_ent_type(&field.ty)
            )
            .unwrap();
            if model.primary_fields.contains(&field.name) {
                writeln!(out, "    primary").unwrap();
            }
            if let Some(source_name) = &field.source_name {
                writeln!(out, "    source {}", quote_ent_string(source_name)).unwrap();
            }
            if let Some(json_name) = &field.json_name {
                writeln!(out, "    json_name {}", quote_ent_string(json_name)).unwrap();
            }
            if field.json_omit_empty {
                writeln!(out, "    json_omit_empty").unwrap();
            }
            if field.auto_increment {
                writeln!(out, "    auto_increment").unwrap();
            }
            if field.immutable {
                writeln!(out, "    immutable").unwrap();
            }
            if field.sensitive {
                writeln!(out, "    sensitive").unwrap();
            }
            if let Some(reason) = &field.deprecated {
                if reason.is_empty() {
                    writeln!(out, "    deprecated").unwrap();
                } else {
                    writeln!(out, "    deprecated {}", quote_ent_string(reason)).unwrap();
                }
            }
            if field.required_on_create {
                writeln!(out, "    required_on_create").unwrap();
            }
            if field.validation.not_empty {
                writeln!(out, "    not_empty").unwrap();
            }
            if let Some(min_len) = field.validation.min_len {
                writeln!(out, "    min_len {min_len}").unwrap();
            }
            if let Some(max_len) = field.validation.max_len {
                writeln!(out, "    max_len {max_len}").unwrap();
            }
            if let Some(min_byte_len) = field.validation.min_byte_len {
                writeln!(out, "    min_byte_len {min_byte_len}").unwrap();
            }
            if let Some(max_byte_len) = field.validation.max_byte_len {
                writeln!(out, "    max_byte_len {max_byte_len}").unwrap();
            }
            if let Some(min) = &field.validation.min {
                writeln!(out, "    min {min}").unwrap();
            }
            if let Some(max) = &field.validation.max {
                writeln!(out, "    max {max}").unwrap();
            }
            if !field.validation.enum_values.is_empty() {
                let values = field
                    .validation
                    .enum_values
                    .iter()
                    .map(|value| quote_ent_string(value))
                    .collect::<Vec<_>>()
                    .join(", ");
                writeln!(out, "    enum {values}").unwrap();
            }
            if let Some(value) = &field.validation.contains {
                writeln!(out, "    contains {}", quote_ent_string(value)).unwrap();
            }
            if let Some(value) = &field.validation.starts_with {
                writeln!(out, "    starts_with {}", quote_ent_string(value)).unwrap();
            }
            if let Some(value) = &field.validation.ends_with {
                writeln!(out, "    ends_with {}", quote_ent_string(value)).unwrap();
            }
            if let Some(value) = &field.validation.not_contains {
                writeln!(out, "    not_contains {}", quote_ent_string(value)).unwrap();
            }
            if let Some(value) = &field.validation.not_starts_with {
                writeln!(out, "    not_starts_with {}", quote_ent_string(value)).unwrap();
            }
            if let Some(value) = &field.validation.not_ends_with {
                writeln!(out, "    not_ends_with {}", quote_ent_string(value)).unwrap();
            }
            if let Some(value) = &field.validation.match_pattern {
                writeln!(out, "    match {}", quote_ent_string(value)).unwrap();
            }
            if field.validation.positive {
                writeln!(out, "    positive").unwrap();
            }
            if field.validation.non_negative {
                writeln!(out, "    non_negative").unwrap();
            }
            if field.validation.negative {
                writeln!(out, "    negative").unwrap();
            }
            if field.validation.non_positive {
                writeln!(out, "    non_positive").unwrap();
            }
            if let Some(update_default) = &field.update_default {
                writeln!(out, "    update_default {update_default}").unwrap();
            }
            if let Some(client_default_value) = &field.client_default_value {
                writeln!(
                    out,
                    "    client_default {}",
                    quote_ent_string(client_default_value)
                )
                .unwrap();
            }
            if field_unique {
                writeln!(out, "    unique").unwrap();
            }
            if field_indexed {
                writeln!(out, "    index").unwrap();
            }
            if let Some(default_value) = &field.default_value {
                writeln!(out, "    default {}", quote_ent_string(default_value)).unwrap();
            }
            if let Some(comment) = &field.comment {
                writeln!(out, "    comment {}", quote_ent_string(comment)).unwrap();
            }
            render_ent_annotations(&mut out, "    ", &field.annotations);
            writeln!(out, "  }}").unwrap();
            writeln!(out).unwrap();
        }

        for index in &model.indexes {
            if index.annotations.is_empty()
                && (index
                    .fields
                    .first()
                    .is_some_and(|field| is_default_field_unique_index(index, field))
                    || index
                        .fields
                        .first()
                        .is_some_and(|field| is_default_field_index(index, field)))
            {
                continue;
            }
            writeln!(out, "  index {} {{", index.name).unwrap();
            writeln!(out, "    fields {}", index.fields.join(", ")).unwrap();
            if index.unique {
                writeln!(out, "    unique").unwrap();
            }
            render_ent_annotations(&mut out, "    ", &index.annotations);
            writeln!(out, "  }}").unwrap();
            writeln!(out).unwrap();
        }

        for edge in &model.edges {
            if let Some(through) = &edge.through {
                if let Some(inverse_ref) = &edge.inverse_ref {
                    writeln!(
                        out,
                        "  edge From({}, {}.Type).Ref({}).Through({}, {}.Type) {{",
                        quote_ent_string(&edge.name),
                        to_pascal_case(&edge.target),
                        quote_ent_string(inverse_ref),
                        quote_ent_string(&through.name),
                        to_pascal_case(&through.model)
                    )
                    .unwrap();
                } else {
                    writeln!(
                        out,
                        "  edge To({}, {}.Type).Through({}, {}.Type) {{",
                        quote_ent_string(&edge.name),
                        to_pascal_case(&edge.target),
                        quote_ent_string(&through.name),
                        to_pascal_case(&through.model)
                    )
                    .unwrap();
                }
            } else if let Some(inverse_ref) = &edge.inverse_ref {
                writeln!(
                    out,
                    "  edge From({}, {}.Type).Ref({}) {{",
                    quote_ent_string(&edge.name),
                    to_pascal_case(&edge.target),
                    quote_ent_string(inverse_ref)
                )
                .unwrap();
            } else {
                writeln!(out, "  edge {} {{", edge.name).unwrap();
                writeln!(out, "    to {}", to_pascal_case(&edge.target)).unwrap();
                if !edge.implicit_field {
                    writeln!(out, "    field {}", edge.field).unwrap();
                    writeln!(out, "    ref {}", edge.ref_field).unwrap();
                } else if let Some(storage_column) = &edge.storage_column {
                    writeln!(
                        out,
                        "    storage_key Column({})",
                        quote_ent_string(storage_column)
                    )
                    .unwrap();
                }
            }
            if !edge.storage_columns.is_empty() {
                let columns = edge
                    .storage_columns
                    .iter()
                    .map(|column| quote_ent_string(column))
                    .collect::<Vec<_>>()
                    .join(", ");
                writeln!(out, "    storage_key Columns({columns})").unwrap();
            }
            if edge.unique {
                writeln!(out, "    unique").unwrap();
            }
            if edge.required {
                writeln!(out, "    required").unwrap();
            }
            if edge.immutable {
                writeln!(out, "    immutable").unwrap();
            }
            if let Some(comment) = &edge.comment {
                writeln!(out, "    comment {}", quote_ent_string(comment)).unwrap();
            }
            render_ent_annotations(&mut out, "    ", &edge.annotations);
            writeln!(out, "  }}").unwrap();
            writeln!(out).unwrap();
        }

        writeln!(out, "}}").unwrap();
        writeln!(out).unwrap();
    }

    out
}

fn render_ent_annotations(out: &mut String, indent: &str, annotations: &[ModelAnnotation]) {
    use std::fmt::Write as _;
    if annotations.is_empty() {
        return;
    }
    let expressions = annotations
        .iter()
        .map(|annotation| annotation.expression.as_str())
        .collect::<Vec<_>>()
        .join(", ");
    writeln!(out, "{indent}Annotations({expressions})").unwrap();
}

fn quote_ent_string(value: &str) -> String {
    format!(
        "\"{}\"",
        value
            .replace('\\', "\\\\")
            .replace('"', "\\\"")
            .replace('\n', "\\n")
    )
}

fn rust_type_to_ent_type(ty: &str) -> String {
    if let Some(inner) = optional_inner_type(ty) {
        return format!("{}?", rust_type_to_ent_type(inner));
    }
    if ty == "Vec<u8>" {
        return "bytes".to_string();
    }
    if let Some(inner) = ty
        .strip_prefix("Vec<")
        .and_then(|value| value.strip_suffix('>'))
    {
        return format!("[]{}", rust_type_to_ent_type(inner));
    }
    match ty {
        "String" => "string".to_string(),
        "DateTime" => "timestamp".to_string(),
        "DateTimeUtc" => "timestamptz".to_string(),
        "serde_json::Value" => "json".to_string(),
        "rust_decimal::Decimal" => "decimal".to_string(),
        other => other.to_string(),
    }
}

