    #[test]
    fn new_model_projects_default_to_sea_orm() {
        let out = temp_model_output("default-sea-orm");

        for mode in [GenerateMode::Create, GenerateMode::Force] {
            assert_eq!(
                resolve_model_orm(&out, mode, None, false).expect("resolve default ORM"),
                ModelOrm::SeaOrm
            );
        }
        assert_eq!(
            resolve_model_orm(&out, GenerateMode::Create, Some(ModelOrm::Toasty), false)
                .expect("resolve explicit Toasty ORM"),
            ModelOrm::Toasty
        );
    }

    #[test]
    fn model_update_inherits_generated_orm_and_requires_explicit_switch() {
        let out = temp_model_output("orm-inheritance");
        fs::create_dir_all(out.join("src/model")).expect("create model directory");
        fs::write(
            out.join("src/model/mod.rs"),
            format!("{MODEL_GENERATED_MARKER}\n{MODEL_ORM_MARKER_PREFIX}sea-orm\n"),
        )
        .expect("write ORM marker");

        assert_eq!(
            resolve_model_orm(&out, GenerateMode::Update, None, false).expect("inherit ORM"),
            ModelOrm::SeaOrm
        );
        let error = resolve_model_orm(&out, GenerateMode::Update, Some(ModelOrm::Toasty), false)
            .expect_err("implicit ORM switch must fail");
        assert!(error.to_string().contains("--switch-orm"));
        assert_eq!(
            resolve_model_orm(&out, GenerateMode::Update, Some(ModelOrm::Toasty), true)
                .expect("explicit ORM switch"),
            ModelOrm::Toasty
        );

        fs::write(
            out.join("src/model/mod.rs"),
            format!("{MODEL_GENERATED_MARKER}\n{MODEL_ORM_MARKER_PREFIX}toasty\n"),
        )
        .expect("write Toasty ORM marker");
        assert_eq!(
            resolve_model_orm(&out, GenerateMode::Update, None, false)
                .expect("inherit existing Toasty ORM"),
            ModelOrm::Toasty
        );

        fs::remove_dir_all(&out).expect("remove temporary model directory");
    }

    #[test]
    fn legacy_model_update_infers_orm_from_manifest() {
        let out = temp_model_output("legacy-orm-inheritance");
        fs::create_dir_all(&out).expect("create output directory");
        fs::write(
            out.join("Cargo.toml"),
            "[package]\nname = \"legacy-model\"\nversion = \"0.1.0\"\n\n[dependencies]\nsea-orm = \"1\"\n",
        )
        .expect("write manifest");

        assert_eq!(
            resolve_model_orm(&out, GenerateMode::Update, None, false).expect("infer legacy ORM"),
            ModelOrm::SeaOrm
        );

        fs::remove_dir_all(&out).expect("remove temporary model directory");
    }

    #[test]
    fn parses_model_blocks() {
        let source = r#"
        model User {
            table: users
            primary: id
            cache: true
            cache_key: id
            cache_prefix: account
            cache_ttl_secs: 300
            negative_cache_ttl_secs: 30
            soft_delete: deleted
            tenant: tenant_id
            unique_index: tenant_id,name
            field id i64
            field tenant_id String
            field name String
            field deleted bool
        }
        "#;

        let models = parse_models(source).expect("parse");
        assert_eq!(models.len(), 1);
        assert_eq!(models[0].name, "User");
        assert_eq!(models[0].table, "users");
        assert_eq!(models[0].primary, "id");
        assert!(models[0].cache);
        assert_eq!(models[0].cache_keys, vec!["id"]);
        assert_eq!(models[0].cache_prefix.as_deref(), Some("account"));
        assert_eq!(models[0].negative_cache_ttl_secs, Some(30));
        assert_eq!(models[0].soft_delete.as_deref(), Some("deleted"));
        assert_eq!(models[0].tenant.as_deref(), Some("tenant_id"));
        assert_eq!(models[0].indexes.len(), 1);
        assert_eq!(models[0].indexes[0].fields, vec!["tenant_id", "name"]);
        assert!(models[0].indexes[0].unique);
    }

    #[test]
    fn rejects_invalid_generated_model_rust_names() {
        let invalid_model = parse_models(
            r#"
        model 123-user {
            field id i64
        }
        "#,
        )
        .expect_err("invalid model");
        assert!(invalid_model
            .to_string()
            .contains("model `123-user` generates invalid Rust module `123_user`"));

        let invalid_field = parse_models(
            r#"
        model User {
            field 123-name String
        }
        "#,
        )
        .expect_err("invalid field");
        assert!(invalid_field
            .to_string()
            .contains("model `User` field `123-name` generates invalid Rust field `123_name`"));

        let duplicate_field = parse_models(
            r#"
        model User {
            field display-name String
            field display_name String
        }
        "#,
        )
        .expect_err("duplicate field");
        assert!(duplicate_field.to_string().contains(
            "duplicate generated model field `display_name` in model `User`: display-name and display_name"
        ));

        let duplicate_model = parse_models(
            r#"
        model user-profile {
            field id i64
        }

        model user_profile {
            field id i64
        }
        "#,
        )
        .expect_err("duplicate model");
        assert!(duplicate_model.to_string().contains(
            "duplicate generated model module `user_profile`: user-profile and user_profile"
        ));
    }

    #[test]
    fn ent_immutable_fields_are_create_only() {
        let source = r#"
        entity User {
            table "users"
            field id: i64 {
                primary
            }
            field name: string {
            }
            field created_at: i64 {
                immutable
            }
        }
        "#;

        let models = parse_models_with_format(source, ModelFormat::Ent).expect("parse ent");
        let model = &models[0];
        let created_at = model
            .fields
            .iter()
            .find(|field| field.name == "created_at")
            .expect("created_at");
        assert!(created_at.immutable);

        let ent = render_ent_schema(&models);
        assert!(ent.contains("immutable"));

        let sea_orm = render_model_module(model);
        assert!(sea_orm.contains("pub fn set_created_at(mut self, value: i64) -> Self"));
        assert!(!sea_orm.contains("pub struct UserUpdate<'repo, 'ctx> {\n    repo: &'repo UserRepository<'ctx>,\n    id: i64,\n    created_at: Option<i64>,"));
        assert!(!sea_orm.contains("active.created_at = Set(value);"));

        let toasty = render_toasty_model_module(model);
        assert!(toasty.contains("pub fn set_created_at(mut self, value: i64) -> Self"));
        assert!(!toasty.contains("pub struct UserUpdate<'a> {\n    db: &'a mut dyn toasty::Executor,\n    id: i64,\n    created_at: Option<i64>,"));
        assert!(!toasty.contains("model.created_at = value;"));
    }

