    #[test]
    fn ent_field_directives_accept_builder_style_calls() {
        let source = r#"
        entity User {
            table "users"
            field id: i64 {
                Primary()
            }
            field display_name: string {
                StorageKey("display-name")
                Unique()
                Sensitive()
                MinLen(3)
                ClientDefault("guest")
            }
            field nickname: string {
                Optional()
            }
            field bio: string {
                Nillable()
            }
            field String("alias").Optional().Nillable() {
            }
            field String("locale").Nillable().Default("en") {
            }
        }
        "#;

        let models = parse_models_with_format(source, ModelFormat::Ent).expect("parse ent");
        let model = &models[0];
        assert_eq!(model.primary, "id");

        let display_name = model
            .fields
            .iter()
            .find(|field| field.name == "display_name")
            .expect("display_name field");
        assert_eq!(display_name.source_name.as_deref(), Some("display-name"));
        assert!(display_name.sensitive);
        assert_eq!(display_name.validation.min_byte_len, Some(3));
        assert_eq!(display_name.client_default_value.as_deref(), Some("guest"));

        let nickname = model
            .fields
            .iter()
            .find(|field| field.name == "nickname")
            .expect("nickname field");
        assert_eq!(nickname.ty, "Option<String>");
        assert!(!nickname.required_on_create);
        let bio = model
            .fields
            .iter()
            .find(|field| field.name == "bio")
            .expect("bio field");
        assert_eq!(bio.ty, "Option<String>");
        assert!(bio.required_on_create);
        let alias = model
            .fields
            .iter()
            .find(|field| field.name == "alias")
            .expect("alias field");
        assert_eq!(alias.ty, "Option<String>");
        assert!(!alias.required_on_create);
        let locale = model
            .fields
            .iter()
            .find(|field| field.name == "locale")
            .expect("locale field");
        assert_eq!(locale.ty, "Option<String>");
        assert!(locale.required_on_create);
        assert_eq!(locale.default_value.as_deref(), Some("en"));

        let ent = render_ent_schema(&models);
        assert!(ent.contains("source \"display-name\""));
        assert!(ent.contains("unique"));
        assert!(ent.contains("sensitive"));
        assert!(ent.contains("min_byte_len 3"));
        assert!(ent.contains("client_default \"guest\""));
        assert!(ent.contains("field nickname: string? {"));
        assert!(ent.contains("field bio: string? {\n    required_on_create"));
        assert!(ent.contains("field alias: string? {"));
        assert!(ent.contains("field locale: string? {\n    required_on_create"));

        let sea_orm = render_model_module(model);
        assert!(sea_orm.contains("#[sea_orm(column_name = \"display-name\")]"));
        assert!(sea_orm.contains(
            "display_name: self.display_name.map(Set).unwrap_or_else(|| Set(\"guest\".to_string()))"
        ));
        assert!(sea_orm.contains("display_name validation failed: byte length must be at least 3"));
        assert!(sea_orm.contains(
            "if !matches!(self.bio.as_ref(), Some(Some(_))) { anyhow::bail!(\"required field `bio` cannot be null\"); }"
        ));
        assert_eq!(
            sea_orm
                .matches("if matches!(self.bio.as_ref(), Some(None))")
                .count(),
            3
        );
        assert_eq!(
            sea_orm
                .matches("if matches!(self.locale.as_ref(), Some(None))")
                .count(),
            4
        );
        assert!(!sea_orm.contains("fn clear_bio"));
        assert!(!sea_orm.contains("fn clear_locale"));
        assert!(sea_orm.contains("fn clear_nickname"));
        assert!(sea_orm.contains("fn clear_alias"));

        let toasty = render_toasty_model_module(model);
        assert!(toasty.contains(
            "if !matches!(self.bio.as_ref(), Some(Some(_))) { return Err(toasty::Error::invalid_record_count(\"required field `bio` cannot be null\")); }"
        ));
        assert_eq!(
            toasty
                .matches("if matches!(self.bio.as_ref(), Some(None))")
                .count(),
            2
        );
        assert_eq!(
            toasty
                .matches("if matches!(self.locale.as_ref(), Some(None))")
                .count(),
            3
        );
        assert!(!toasty.contains("fn clear_bio"));
        assert!(!toasty.contains("fn clear_locale"));
        assert!(toasty.contains("fn clear_nickname"));
        assert!(toasty.contains("fn clear_alias"));
    }

    #[test]
    fn ent_sensitive_fields_are_redacted_from_debug_output() {
        let source = r#"
        entity User {
            table "users"
            field id: i64 {
                primary
            }
            field username: string {
            }
            field password: string {
                sensitive
            }
        }
        "#;

        let models = parse_models_with_format(source, ModelFormat::Ent).expect("parse ent");
        let model = &models[0];
        let password = model
            .fields
            .iter()
            .find(|field| field.name == "password")
            .expect("password field");
        assert!(password.sensitive);

        let ent = render_ent_schema(&models);
        assert!(ent.contains("field password: string {\n    sensitive\n  }"));

        let sea_orm = render_model_module(model);
        assert!(sea_orm.contains(
            "#[derive(Clone, PartialEq, Eq, Serialize, Deserialize, DeriveEntityModel)]"
        ));
        assert!(sea_orm.contains("impl std::fmt::Debug for Model"));
        assert!(sea_orm.contains("debug.field(\"username\", &self.username);"));
        assert!(sea_orm.contains("debug.field(\"password\", &\"<sensitive>\");"));
        assert!(sea_orm.contains("#[serde(skip)]\n    pub password: String"));
        assert!(!sea_orm.contains(
            "#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, DeriveEntityModel)]"
        ));

        let toasty = render_toasty_model_module(model);
        assert!(
            toasty.contains("#[derive(Clone, PartialEq, Serialize, Deserialize, toasty::Model)]")
        );
        assert!(toasty.contains("impl std::fmt::Debug for User"));
        assert!(toasty.contains("debug.field(\"username\", &self.username);"));
        assert!(toasty.contains("debug.field(\"password\", &\"<sensitive>\");"));
        assert!(toasty.contains("#[serde(skip)]\n    pub password: String"));
        assert!(!toasty
            .contains("#[derive(Clone, Debug, PartialEq, Serialize, Deserialize, toasty::Model)]"));
    }

    #[test]
    fn ent_field_invariants_fail_fast_like_ent() {
        let optional_id = r#"
        entity User {
            field id: i64? {
                primary
            }
        }
        "#;
        let err = parse_models_with_format(optional_id, ModelFormat::Ent)
            .expect_err("optional primary field should fail");
        assert!(err
            .to_string()
            .contains("primary field `id` cannot be optional"));

        let unique_static_default = r#"
        entity User {
            field id: i64 {
                primary
            }
            field String("email").Unique().Default("unknown@example.com") {
            }
        }
        "#;
        let err = parse_models_with_format(unique_static_default, ModelFormat::Ent)
            .expect_err("unique static default should fail");
        assert!(err
            .to_string()
            .contains("unique field `email` cannot have a static default value"));

        let sensitive_tag = r#"
        entity User {
            field id: i64 {
                primary
            }
            field String("secret").Sensitive().StructTag(`json:"secretValue,omitempty"`) {
            }
        }
        "#;
        let err = parse_models_with_format(sensitive_tag, ModelFormat::Ent)
            .expect_err("sensitive struct tag should fail");
        assert!(err
            .to_string()
            .contains("sensitive field `secret` cannot have JSON struct-tag metadata"));

        let unique_dynamic_default = r#"
        entity User {
            field UUID("id", uuid.UUID{}).Primary().Unique().DefaultFunc(uuid.NewString) {
            }
        }
        "#;
        parse_models_with_format(unique_dynamic_default, ModelFormat::Ent)
            .expect("unique function default should remain valid");
    }

    #[test]
    fn ent_edge_field_invariants_fail_fast_like_ent() {
        let err = parse_models_with_format(
            r#"
            entity User {
                field Int64("id").Primary() {
                }
            }
            entity Profile {
                field Int64("id").Primary() {
                }
                field Int64("user_id").Optional() {
                }
                edge To("user", User.Type).Field("user_id") {
                }
            }
            "#,
            ModelFormat::Ent,
        )
        .expect_err("edge fields require to-one cardinality");
        assert!(err
            .to_string()
            .contains("edge `user` with field `user_id` must be unique"));

        let invalid = [
            (
                r#"
                entity User {
                    field Int64("id").Primary() {
                    }
                }
                entity Profile {
                    field Int64("id").Primary() {
                    }
                    field Int64("user_id").Optional() {
                    }
                    edge To("user", User.Type).Field("user_id").Unique().Required() {
                    }
                }
                "#,
                "edge field `user_id` is optional, but edge `user` is required",
            ),
            (
                r#"
                entity User {
                    field Int64("id").Primary() {
                    }
                }
                entity Profile {
                    field Int64("id").Primary() {
                    }
                    field Int64("user_id") {
                    }
                    edge To("user", User.Type).Field("user_id").Unique() {
                    }
                }
                "#,
                "edge `user` is optional, but edge field `user_id` is required",
            ),
            (
                r#"
                entity User {
                    field Int64("id").Primary() {
                    }
                }
                entity Profile {
                    field Int64("id").Primary() {
                    }
                    field Int64("user_id").Optional().Immutable() {
                    }
                    edge To("user", User.Type).Field("user_id").Unique() {
                    }
                }
                "#,
                "edge field `user_id` is immutable, but edge `user` is not",
            ),
            (
                r#"
                entity User {
                    field Int64("id").Primary() {
                    }
                }
                entity Profile {
                    field Int64("id").Primary() {
                    }
                    field Int64("user_id").Optional() {
                    }
                    edge To("user", User.Type).Field("user_id").Unique().Immutable() {
                    }
                }
                "#,
                "edge `user` is immutable, but edge field `user_id` is not",
            ),
        ];

        for (source, expected) in invalid {
            let err = parse_models_with_format(source, ModelFormat::Ent)
                .expect_err("edge and explicit field metadata should agree");
            assert!(err.to_string().contains(expected), "{err:#}");
        }

        parse_models_with_format(
            r#"
            entity User {
                field Int64("id").Primary() {
                }
            }
            entity Profile {
                field Int64("id").Primary() {
                }
                field Int64("user_id").Nillable().Immutable() {
                }
                edge To("user", User.Type).Field("user_id").Unique().Required().Immutable() {
                }
            }
            "#,
            ModelFormat::Ent,
        )
        .expect("required Nillable fields retain Ent create semantics");
    }

    #[test]
    fn ent_string_field_validators_generate_mutation_checks() {
        let source = r#"
        entity User {
            table "users"
            field id: i64 {
                primary
            }
            field name: string {
                not_empty
                min_len 3
                max_len 32
            }
            field nickname: string? {
                max_len 64
            }
            field status: string {
                enum active, disabled
            }
            field code: string {
                starts_with usr_
                contains "-"
                ends_with _v1
                not_contains " "
                not_starts_with tmp_
                not_ends_with _draft
            }
        }
        "#;

        let models = parse_models_with_format(source, ModelFormat::Ent).expect("parse ent");
        let model = &models[0];
        let name = model
            .fields
            .iter()
            .find(|field| field.name == "name")
            .expect("name field");
        assert!(name.validation.not_empty);
        assert_eq!(name.validation.min_len, Some(3));
        assert_eq!(name.validation.max_len, Some(32));

        let ent = render_ent_schema(&models);
        assert!(ent.contains("not_empty"));
        assert!(ent.contains("min_len 3"));
        assert!(ent.contains("max_len 32"));
        assert!(ent.contains("enum \"active\", \"disabled\""));
        assert!(ent.contains("starts_with \"usr_\""));
        assert!(ent.contains("contains \"-\""));
        assert!(ent.contains("ends_with \"_v1\""));
        assert!(ent.contains("not_contains \" \""));
        assert!(ent.contains("not_starts_with \"tmp_\""));
        assert!(ent.contains("not_ends_with \"_draft\""));

        let sea_orm = render_model_module(model);
        assert!(sea_orm.contains("if let Some(value) = self.name.as_ref() {"));
        assert!(sea_orm.contains(
            "if value.is_empty() { anyhow::bail!(\"name validation failed: must not be empty\"); }"
        ));
        assert!(!sea_orm.contains("value.trim().is_empty()"));
        assert!(sea_orm.contains(
            "if value.chars().count() < 3 { anyhow::bail!(\"name validation failed: length must be at least 3\"); }"
        ));
        assert!(sea_orm.contains("if let Some(Some(value)) = self.nickname.as_ref() {"));
        assert!(sea_orm.contains(
            "if value.chars().count() > 64 { anyhow::bail!(\"nickname validation failed: length must be at most 64\"); }"
        ));
        assert!(sea_orm.contains(
            "if !matches!(value.as_str(), \"active\" | \"disabled\") { anyhow::bail!(\"status validation failed: value is not allowed\"); }"
        ));
        assert!(sea_orm.contains(
            "if !value.contains(\"-\") { anyhow::bail!(\"code validation failed: must contain required substring\"); }"
        ));
        assert!(sea_orm.contains(
            "if !value.starts_with(\"usr_\") { anyhow::bail!(\"code validation failed: must start with required prefix\"); }"
        ));
        assert!(sea_orm.contains(
            "if !value.ends_with(\"_v1\") { anyhow::bail!(\"code validation failed: must end with required suffix\"); }"
        ));
        assert!(sea_orm.contains(
            "if value.contains(\" \") { anyhow::bail!(\"code validation failed: must not contain forbidden substring\"); }"
        ));
        assert!(sea_orm.contains(
            "if value.starts_with(\"tmp_\") { anyhow::bail!(\"code validation failed: must not start with forbidden prefix\"); }"
        ));
        assert!(sea_orm.contains(
            "if value.ends_with(\"_draft\") { anyhow::bail!(\"code validation failed: must not end with forbidden suffix\"); }"
        ));

        let toasty = render_toasty_model_module(model);
        assert!(toasty.contains("if let Some(value) = self.name.as_ref() {"));
        assert!(toasty.contains(
            "return Err(toasty::Error::invalid_record_count(\"name validation failed: must not be empty\"));"
        ));
        assert!(toasty.contains(
            "return Err(toasty::Error::invalid_record_count(\"nickname validation failed: length must be at most 64\"));"
        ));
        assert!(toasty.contains(
            "return Err(toasty::Error::invalid_record_count(\"status validation failed: value is not allowed\"));"
        ));
        assert!(toasty.contains(
            "return Err(toasty::Error::invalid_record_count(\"code validation failed: must contain required substring\"));"
        ));
        assert!(toasty.contains(
            "return Err(toasty::Error::invalid_record_count(\"code validation failed: must start with required prefix\"));"
        ));
        assert!(toasty.contains(
            "return Err(toasty::Error::invalid_record_count(\"code validation failed: must end with required suffix\"));"
        ));
        assert!(toasty.contains(
            "return Err(toasty::Error::invalid_record_count(\"code validation failed: must not contain forbidden substring\"));"
        ));
        assert!(toasty.contains(
            "return Err(toasty::Error::invalid_record_count(\"code validation failed: must not start with forbidden prefix\"));"
        ));
        assert!(toasty.contains(
            "return Err(toasty::Error::invalid_record_count(\"code validation failed: must not end with forbidden suffix\"));"
        ));
    }

    #[test]
    fn ent_string_byte_and_rune_length_validators_generate_distinct_checks() {
        let source = r#"
        entity User {
            table "users"
            field Int64("id").Primary() {
            }
            field String("handle").MinLen(3).MaxLen(12) {
            }
            field String("display_name").MinRuneLen(2).MaxRuneLen(8) {
            }
        }
        "#;

        let models = parse_models_with_format(source, ModelFormat::Ent).expect("parse ent");
        let model = &models[0];
        let handle = model
            .fields
            .iter()
            .find(|field| field.name == "handle")
            .expect("handle field");
        assert_eq!(handle.validation.min_byte_len, Some(3));
        assert_eq!(handle.validation.max_byte_len, Some(12));
        let display_name = model
            .fields
            .iter()
            .find(|field| field.name == "display_name")
            .expect("display_name field");
        assert_eq!(display_name.validation.min_len, Some(2));
        assert_eq!(display_name.validation.max_len, Some(8));

        let ent = render_ent_schema(&models);
        assert!(ent.contains("min_byte_len 3"));
        assert!(ent.contains("max_byte_len 12"));
        assert!(ent.contains("min_len 2"));
        assert!(ent.contains("max_len 8"));

        let sea_orm = render_model_module(model);
        assert!(sea_orm.contains(
            "if value.len() < 3 { anyhow::bail!(\"handle validation failed: byte length must be at least 3\"); }"
        ));
        assert!(sea_orm.contains(
            "if value.len() > 12 { anyhow::bail!(\"handle validation failed: byte length must be at most 12\"); }"
        ));
        assert!(sea_orm.contains(
            "if value.chars().count() < 2 { anyhow::bail!(\"display_name validation failed: length must be at least 2\"); }"
        ));
        assert!(sea_orm.contains(
            "if value.chars().count() > 8 { anyhow::bail!(\"display_name validation failed: length must be at most 8\"); }"
        ));
    }

