    #[test]
    fn ent_field_id_annotation_preserves_composite_primary_keys() {
        let source = r#"
        entity Like {
            Table("likes")
            Annotations(field.ID("user_id", "tweet_id"))
            field Time("liked_at").Default(time.Now) {
            }
            field Int64("user_id") {
            }
            field Int64("tweet_id") {
            }
        }
        "#;

        let models = parse_models_with_format(source, ModelFormat::Ent).expect("composite id");
        assert_eq!(models[0].primary, "user_id");
        assert_eq!(models[0].primary_fields, ["user_id", "tweet_id"]);
        assert!(models[0].cache_keys.is_empty());

        let ent = render_ent_schema(&models);
        let reparsed = parse_models_with_format(&ent, ModelFormat::Ent).expect("round trip");
        assert_eq!(reparsed[0].primary_fields, models[0].primary_fields);
        let sea_orm = render_model_module(&models[0]);
        assert_eq!(sea_orm.matches("#[sea_orm(primary_key)]").count(), 2);
        assert!(sea_orm.contains("pub struct LikeKey"));
        assert!(sea_orm.contains("Entity::find_by_id((key.user_id, key.tweet_id))"));
        assert!(sea_orm.contains("Entity::delete_by_id((key.user_id, key.tweet_id))"));
        assert!(sea_orm.contains("pub async fn update_by_key"));
        assert!(sea_orm.contains("model.user_id = key.user_id;"));
        assert!(sea_orm.contains("pub async fn delete_many_by_keys"));
        assert!(sea_orm.contains("pub fn update_one(&self, key: LikeKey)"));
        assert!(sea_orm.contains("pub struct LikeUpdate<'repo, 'ctx>"));
        assert!(sea_orm.contains("user_id: Set(self.key.user_id)"));
        assert!(sea_orm.contains("tweet_id: Set(self.key.tweet_id)"));
        assert!(sea_orm.contains("pub fn delete_one(&self, key: LikeKey)"));
        assert!(sea_orm.contains("pub async fn upsert(&self, model: Model)"));
        assert!(sea_orm.contains("OnConflict::columns([Column::UserId, Column::TweetId])"));
        assert!(sea_orm.contains("update_columns([Column::LikedAt])"));
        assert!(sea_orm.contains("let upsert_key = (model.user_id, model.tweet_id);"));
        assert!(sea_orm.contains("Entity::find_by_id(upsert_key).one(&db)"));
        assert!(sea_orm.contains(
            "let insert_key = (active.user_id.clone().unwrap(), active.tweet_id.clone().unwrap());"
        ));
        assert!(sea_orm.contains("Entity::insert(active).exec_without_returning(&db)"));
        assert!(sea_orm.contains("inserted Like could not be reloaded"));
        assert!(sea_orm
            .contains("pub async fn add_liked_at(mut self, delta: i64) -> anyhow::Result<Model>"));
        assert!(sea_orm.contains("query = query.where_(user_id_eq(key.user_id.clone()))"));
        assert!(sea_orm.contains("query = query.where_(tweet_id_eq(key.tweet_id.clone()))"));
        assert!(sea_orm.contains("self.repo.find_by_key(key).await?"));
        let toasty = render_toasty_model_module(&models[0]);
        assert_eq!(toasty.matches("#[key]").count(), 2);
        assert!(toasty.contains("pub struct LikeKey"));
        assert!(toasty.contains("pub async fn find_by_key"));
        assert!(
            toasty.contains("where_(user_id_eq(key.user_id)).where_(tweet_id_eq(key.tweet_id))")
        );
        assert!(toasty.contains("pub async fn update_by_key"));
        assert!(toasty.contains("pub async fn delete_many_by_keys"));
        assert!(toasty.contains("pub fn update_one(db: &mut dyn toasty::Executor, key: LikeKey)"));
        assert!(toasty.contains("LikeRepository::find_by_key(&mut *self.db, &self.key)"));
        assert!(toasty.contains("pub fn delete_one(db: &mut dyn toasty::Executor, key: LikeKey)"));
        assert!(toasty.contains("pub async fn upsert("));
        assert!(toasty.contains(".where_(user_id_eq(model.user_id))"));
        assert!(toasty.contains(".where_(tweet_id_eq(model.tweet_id))"));
        assert!(toasty
            .contains("pub async fn add_liked_at(mut self, delta: i64) -> toasty::Result<Like>"));
        assert!(toasty.contains("LikeRepository::find_by_key(&mut *self.db, &key).await?"));
    }

    #[test]
    fn ent_duration_field_builder_maps_to_i64_nanoseconds() {
        let source = r#"
        entity Job {
            Table("jobs")
            field ID("id") {
            }
            field Duration("timeout").Default(5 * time.Second) {
            }
            field Duration("cooldown").Optional().Default(time.Minute) {
            }
        }
        "#;

        let models = parse_models_with_format(source, ModelFormat::Ent).expect("parse ent");
        let model = &models[0];
        let timeout = model
            .fields
            .iter()
            .find(|field| field.name == "timeout")
            .expect("timeout field");
        assert_eq!(timeout.ty, "i64");
        assert_eq!(timeout.default_value.as_deref(), Some("5000000000"));
        let cooldown = model
            .fields
            .iter()
            .find(|field| field.name == "cooldown")
            .expect("cooldown field");
        assert_eq!(cooldown.ty, "Option<i64>");
        assert_eq!(cooldown.default_value.as_deref(), Some("60000000000"));

        let ent = render_ent_schema(&models);
        assert!(ent.contains("field timeout: i64 {"));
        assert!(ent.contains("default \"5000000000\""));
        assert!(ent.contains("field cooldown: i64? {"));
        assert!(ent.contains("default \"60000000000\""));

        let sea_orm = render_model_module(model);
        assert!(
            sea_orm.contains("timeout: self.timeout.map(Set).unwrap_or_else(|| Set(5000000000))")
        );
        assert!(sea_orm.contains(
            "cooldown: self.cooldown.map(Set).unwrap_or_else(|| Set(Some(60000000000)))"
        ));
    }

