    #[test]
    fn ent_edge_immutable_and_metadata_directives_generate_expected_behavior() {
        let source = r#"
        entity User {
            table "users"
            field Int64("id").Primary() {
            }
        }

        entity Profile {
            table "profiles"
            field Int64("id").Primary() {
            }
            field Int64("user_id").Optional().Immutable() {
            }
            field String("tenant_id") {
            }
            edge To("user", User.Type).Field("user_id").Ref("id").Unique().Immutable().Annotations(entgql.Bind()) {
                StorageKey("profile_user_fk")
                Comment("owner relation")
                Immutable()
                Deprecated("use account")
            }
            index Fields("tenant_id", "user_id").Unique().Prefix(64).Desc().IndexType("HASH").Annotations(entgql.OrderField("TENANT_USER")).Where(sql.FieldNEQ("deleted_at", nil)).Deprecated("old lookup") {
                PrefixColumn("tenant_id", 32)
                DescColumns("tenant_id")
                IndexTypes(map[string]string{dialect.MySQL: "FULLTEXT"})
                IncludeColumns("updated_at")
                IndexWhere("active")
                OpClass("bpchar_pattern_ops")
            }
        }
        "#;

        let models = parse_models_with_format(source, ModelFormat::Ent).expect("parse ent");
        let profile = models
            .iter()
            .find(|model| model.name == "Profile")
            .expect("profile");
        let user_edge = profile
            .edges
            .iter()
            .find(|edge| edge.name == "user")
            .expect("user edge");
        assert_eq!(user_edge.target, "User");
        assert_eq!(user_edge.field, "user_id");
        assert_eq!(user_edge.ref_field, "id");
        assert!(user_edge.unique);
        assert!(user_edge.immutable);
        assert!(!user_edge.implicit_field);
        assert_eq!(user_edge.comment.as_deref(), Some("owner relation"));
        assert!(profile.indexes.iter().any(|index| {
            index.unique
                && index.name == "uniq_tenant_id_user_id"
                && index.fields == ["tenant_id", "user_id"]
        }));

        let ent = render_ent_schema(&models);
        assert!(ent.contains("edge user {"));
        assert!(ent.contains("    to User"));
        assert!(ent.contains("    field user_id"));
        assert!(ent.contains("    unique"));
        assert!(ent.contains("index uniq_tenant_id_user_id {"));
        assert!(ent.contains("    fields tenant_id, user_id"));
        assert!(ent.contains("Annotations(entgql.Bind())"));
        assert!(!ent.contains("StorageKey(\"profile_user_fk\")"));
        assert!(ent.contains("    comment \"owner relation\""));
        assert!(ent.contains("    immutable"));
        assert!(!ent.contains("Comment(\"owner relation\")"));
        assert!(!ent.contains("Immutable"));
        assert!(!ent.contains("Deprecated"));
        assert!(!ent.contains("Where"));
        assert!(!ent.contains("Prefix"));
        assert!(!ent.contains("Desc"));
        assert!(!ent.contains("IndexType"));
        assert!(!ent.contains("IncludeColumns"));
        assert!(!ent.contains("IndexWhere"));
        assert!(!ent.contains("OpClass"));

        let sea_orm = render_model_module(profile);
        assert_eq!(
            sea_orm
                .matches("pub fn set_user(mut self, target: &crate::model::UserModel)")
                .count(),
            1
        );
        assert_eq!(
            sea_orm
                .matches("pub fn set_user_id(mut self, value: i64)")
                .count(),
            0
        );

        let toasty = render_toasty_model_module(profile);
        assert_eq!(
            toasty
                .matches("pub fn set_user(mut self, target: &crate::model::User)")
                .count(),
            1
        );
        assert_eq!(
            toasty
                .matches("pub fn set_user_id(mut self, value: i64)")
                .count(),
            0
        );
    }

