    #[test]
    fn parses_sql_model_blocks() {
        let source = r#"
        CREATE TABLE `users` (
            `id` bigint unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY,
            `tenant_id` varchar(64) NOT NULL,
            `name` varchar(255) NOT NULL,
            `nickname` varchar(255) NULL DEFAULT 'guest' COMMENT 'Nickname',
            `config` JSONB NOT NULL DEFAULT '{}'::jsonb,
            `sort_order` INT NOT NULL DEFAULT 100,
            `deleted` tinyint(1) NOT NULL DEFAULT 0,
            `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
            UNIQUE KEY `uniq_users_name` (`name`),
            UNIQUE KEY `uniq_users_name_created_at` (`name`, `created_at`)
        );
        COMMENT ON COLUMN users.nickname IS 'nickname from profile';
        "#;

        let models = parse_models_with_format(source, ModelFormat::Sql).expect("parse");
        assert_eq!(models.len(), 1);
        assert_eq!(models[0].name, "User");
        assert_eq!(models[0].table, "users");
        assert_eq!(models[0].primary, "id");
        assert!(models[0].cache);
        assert_eq!(models[0].cache_keys, vec!["id", "name"]);
        assert_eq!(models[0].indexes.len(), 2);
        assert_eq!(models[0].indexes[1].fields, vec!["name", "created_at"]);
        assert!(models[0].indexes[1].unique);
        assert_eq!(models[0].soft_delete.as_deref(), Some("deleted"));
        assert_eq!(models[0].tenant.as_deref(), Some("tenant_id"));
        assert_eq!(models[0].fields[0].ty, "u64");
        assert_eq!(models[0].fields[3].ty, "Option<String>");
        assert_eq!(models[0].fields[4].ty, "serde_json::Value");
        assert_eq!(models[0].fields[4].default_value.as_deref(), Some("{}"));
        assert_eq!(models[0].fields[5].ty, "i32");
        assert_eq!(
            models[0].fields[3].default_value.as_deref(),
            Some("'guest'")
        );
        assert_eq!(
            models[0].fields[3].comment.as_deref(),
            Some("nickname from profile")
        );
        assert_eq!(
            models[0].fields[7].default_value.as_deref(),
            Some("CURRENT_TIMESTAMP")
        );

        let ent = render_ent_schema(&models);
        assert!(ent.contains("field config: json {"));
        assert!(ent.contains("default \"{}\""));
        let sea_orm = render_model_module(&models[0]);
        assert!(sea_orm.contains("pub config: serde_json::Value"));
        assert!(sea_orm.contains("serde_json::from_str::<serde_json::Value>(\"{}\")"));

        let toasty_models = models_for_orm(&models, ModelOrm::Toasty);
        let toasty = render_toasty_model_module(&toasty_models[0]);
        assert!(toasty.contains("pub config: String"));
    }

    #[test]
    fn parses_standalone_sql_indexes() {
        let source = r#"
        CREATE TABLE public.users (
            id bigint NOT NULL PRIMARY KEY,
            legacy_user_id bigint,
            tenant_id varchar(64) NOT NULL,
            email varchar(255) NOT NULL,
            deleted_at timestamp
        );
        CREATE INDEX idx_users_tenant ON public.users (tenant_id);
        CREATE UNIQUE INDEX idx_users_legacy_user
            ON public.users (legacy_user_id)
            WHERE legacy_user_id IS NOT NULL;
        CREATE INDEX IF NOT EXISTS idx_users_tenant_email
            ON public.users USING btree (tenant_id, email);
        "#;

        let models = parse_models_with_format(source, ModelFormat::Sql).expect("parse indexes");
        let user = &models[0];
        assert_eq!(user.indexes.len(), 3);
        assert_eq!(user.indexes[0].name, "idx_users_tenant");
        assert_eq!(user.indexes[0].fields, ["tenant_id"]);
        assert!(!user.indexes[0].unique);
        assert_eq!(user.indexes[1].name, "idx_users_legacy_user");
        assert_eq!(user.indexes[1].fields, ["legacy_user_id"]);
        assert!(user.indexes[1].unique);
        assert_eq!(
            user.indexes[1].annotations,
            [ModelAnnotation {
                name: "sql.Where".into(),
                expression: "sql.Where(\"legacy_user_id IS NOT NULL\")".into(),
            }]
        );
        assert_eq!(
            user.indexes[2].fields,
            ["tenant_id".to_string(), "email".to_string()]
        );
        assert!(!user.cache_keys.contains(&"legacy_user_id".to_string()));

        let ent = render_ent_schema(&models);
        let reparsed =
            parse_models_with_format(&ent, ModelFormat::Ent).expect("partial index round trip");
        assert_eq!(reparsed[0].indexes, user.indexes);
    }

    #[test]
    fn renders_and_parses_complete_ent_schema() {
        let source = r#"
        CREATE TABLE shop.users (
            id bigint NOT NULL AUTO_INCREMENT,
            tenant_id varchar(64) NOT NULL,
            name varchar(255) NOT NULL COMMENT 'display name',
            email varchar(255) NOT NULL,
            nickname varchar(255) NULL DEFAULT 'guest',
            deleted tinyint(1) NOT NULL DEFAULT 0,
            PRIMARY KEY (id),
            UNIQUE KEY uniq_email (email),
            UNIQUE KEY uniq_users_tenant_name (tenant_id, name)
        );
        "#;

        let sql_models = parse_sql_models(source).expect("parse sql");
        let ent = render_ent_schema(&sql_models);

        assert!(ent.contains("entity User {"));
        assert!(ent.contains("table \"users\""));
        assert!(ent.contains("schema \"shop\""));
        assert!(ent.contains("tenant tenant_id"));
        assert!(ent.contains("soft_delete deleted"));
        assert!(ent.contains("field id: i64 {"));
        assert!(ent.contains("primary"));
        assert!(ent.contains("auto_increment"));
        assert!(ent.contains("field email: string {"));
        assert!(ent.contains("unique"));
        assert!(ent.contains("field nickname: string? {"));
        assert!(ent.contains("default \"'guest'\""));
        assert!(ent.contains("comment \"display name\""));
        assert!(!ent.contains("index uniq_email {"));
        assert!(ent.contains("index uniq_users_tenant_name {"));
        assert!(ent.contains("fields tenant_id, name"));
        assert!(ent.contains("unique"));

        let ent_models = parse_models_with_format(&ent, ModelFormat::Ent).expect("parse ent");
        assert_eq!(ent_models, sql_models);
        let rendered = render_model_module(&ent_models[0]);
        assert!(rendered.contains("pub async fn find_by_email"));
    }

    #[test]
    fn model_generate_writes_ent_schema_before_model_code() {
        let source = r#"
        CREATE TABLE users (
            id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
            tenant_id VARCHAR(64) NOT NULL,
            name VARCHAR(255) NOT NULL,
            deleted TINYINT(1) NOT NULL DEFAULT 0,
            UNIQUE KEY uniq_users_tenant_name (tenant_id, name)
        );
        "#;
        let unique = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("time")
            .as_nanos();
        let out = std::env::temp_dir().join(format!("rozectl-ent-model-out-{unique}"));
        write_minimal_main(&out);

        generate_model_project(
            source,
            &out,
            GenerateOptions::new(GenerateMode::Create, DependencySource::Path),
            ModelFormat::Sql,
            ModelOrm::Toasty,
        )
        .expect("generate");

        let ent = fs::read_to_string(out.join("src/model/schema.ent")).expect("ent read");
        assert!(ent.contains("entity User {"));
        assert!(ent.contains("field name: string {"));

        let from_ent = std::env::temp_dir().join(format!("rozectl-ent-model-from-ent-{unique}"));
        write_minimal_main(&from_ent);
        generate_model_project(
            &ent,
            &from_ent,
            GenerateOptions::new(GenerateMode::Create, DependencySource::Path),
            ModelFormat::Ent,
            ModelOrm::Toasty,
        )
        .expect("generate from ent");

        let sql_model = fs::read_to_string(out.join("src/model/user.rs")).expect("sql model");
        let ent_model = fs::read_to_string(from_ent.join("src/model/user.rs")).expect("ent model");
        assert_eq!(sql_model, ent_model);
    }

    #[test]
    fn imports_foreign_keys_as_ent_edges() {
        let source = r#"
        CREATE TABLE users (
            id bigint NOT NULL AUTO_INCREMENT,
            name varchar(64) NOT NULL,
            PRIMARY KEY (id)
        );

        CREATE TABLE profiles (
            id bigint NOT NULL AUTO_INCREMENT,
            nickname varchar(64) NOT NULL,
            PRIMARY KEY (id)
        );

        CREATE TABLE orders (
            id bigint NOT NULL AUTO_INCREMENT,
            user_id bigint NOT NULL,
            profile_id bigint REFERENCES profiles(id),
            PRIMARY KEY (id),
            CONSTRAINT fk_orders_user FOREIGN KEY (user_id) REFERENCES users(id)
        );
        "#;

        let models = parse_models_with_format(source, ModelFormat::Sql).expect("parse");
        let order = models
            .iter()
            .find(|model| model.name == "Order")
            .expect("order model");
        assert!(order.edges.contains(&ModelEdge {
            name: "user".to_string(),
            target: "User".to_string(),
            field: "user_id".to_string(),
            ref_field: "id".to_string(),
            inverse_ref: None,
            inverse_field_optional: false,
            through: None,
            unique: true,
            required: true,
            immutable: false,
            storage_column: None,
            storage_columns: Vec::new(),
            comment: None,
            implicit_field: false,
            annotations: Vec::new(),
        }));
        assert!(order.edges.contains(&ModelEdge {
            name: "profile".to_string(),
            target: "Profile".to_string(),
            field: "profile_id".to_string(),
            ref_field: "id".to_string(),
            inverse_ref: None,
            inverse_field_optional: false,
            through: None,
            unique: true,
            required: false,
            immutable: false,
            storage_column: None,
            storage_columns: Vec::new(),
            comment: None,
            implicit_field: false,
            annotations: Vec::new(),
        }));

        let ent = render_ent_schema(&models);
        assert!(ent.contains("edge user {"));
        assert!(ent.contains("    to User"));
        assert!(ent.contains("    field user_id"));
        assert!(ent.contains("    ref id"));
        assert!(ent.contains("    required"));

        let reparsed = parse_models_with_format(&ent, ModelFormat::Ent).expect("parse ent");
        let reparsed_order = reparsed
            .iter()
            .find(|model| model.name == "Order")
            .expect("reparsed order model");
        assert_eq!(reparsed_order.edges, order.edges);

        let sea_orm_order = render_model_module(order);
        assert!(sea_orm_order.contains("pub async fn query_user"));
        assert!(sea_orm_order.contains("pub async fn query_profile"));
        assert!(sea_orm_order.contains("pub async fn where_user_with<I>(self, repo: &crate::model::UserRepository<'_>, predicates: I) -> anyhow::Result<Self>"));
        assert!(sea_orm_order.contains("repo.query().where_all(predicates).pluck_id().await?;"));
        assert!(sea_orm_order.contains("Ok(self.where_(user_id_in(values)))"));
        assert!(sea_orm_order
            .contains("pub fn set_user(mut self, target: &crate::model::UserModel) -> Self"));
        assert!(sea_orm_order.contains("self.user_id = Some(target.id);"));
        assert!(sea_orm_order.contains("pub async fn traverse_user"));
        assert!(sea_orm_order
            .contains("let Some(value) = self.profile_id.as_ref() else { return Ok(None); };"));

        let toasty_order = render_toasty_model_module(order);
        assert!(toasty_order.contains("pub async fn query_user"));
        assert!(toasty_order.contains("pub async fn query_profile"));
        assert!(toasty_order.contains(
            "pub async fn where_user_with<I>(mut self, predicates: I) -> toasty::Result<Self>"
        ));
        assert!(toasty_order.contains(
            "UserRepository::query(&mut *self.db).where_all(predicates).pluck_id().await?;"
        ));
        assert!(toasty_order.contains("self.predicates.push(user_id_in(values));"));
        assert!(
            toasty_order.contains("pub fn set_user(mut self, target: &crate::model::User) -> Self")
        );
        assert!(toasty_order.contains("self.user_id = Some(target.id);"));
        assert!(toasty_order.contains("pub async fn traverse_user"));
        assert!(toasty_order
            .contains("let Some(value) = self.profile_id.as_ref() else { return Ok(None); };"));
    }

    #[test]
    fn imports_postgres_named_table_constraints_without_phantom_columns() {
        let source = r#"
        CREATE TABLE accounts (
            id BIGINT NOT NULL,
            tenant_id BIGINT NOT NULL,
            code VARCHAR(64) NOT NULL,
            status VARCHAR(16) NOT NULL,
            CONSTRAINT accounts_pkey PRIMARY KEY (id),
            CONSTRAINT accounts_tenant_code_key UNIQUE (tenant_id, code),
            CONSTRAINT accounts_status_check
                CHECK (status IN ('active', 'disabled')),
            CONSTRAINT accounts_code_check CHECK (char_length(code) > 2 AND code <> 'x,y'),
            CHECK (tenant_id > 0)
        );
        "#;

        let models = parse_models_with_format(source, ModelFormat::Sql).expect("parse");
        let account = models.iter().find(|model| model.name == "Account").unwrap();
        assert_eq!(account.primary, "id");
        assert_eq!(
            account
                .fields
                .iter()
                .map(|field| field.name.as_str())
                .collect::<Vec<_>>(),
            vec!["id", "tenant_id", "code", "status"]
        );
        assert!(account.indexes.iter().any(|index| {
            index.name == "accounts_tenant_code_key"
                && index.unique
                && index.fields == ["tenant_id", "code"]
        }));
    }

