    #[test]
    fn model_update_preserves_extension_file() {
        let unique = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("time")
            .as_nanos();
        let out = std::env::temp_dir().join(format!("rozectl-model-ext-out-{unique}"));
        write_minimal_main(&out);

        let source = r#"
            CREATE TABLE users (
                id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
                name VARCHAR(255) NOT NULL,
                config JSONB NOT NULL DEFAULT '{}'::jsonb
            );
            "#;

        generate_model_project(
            source,
            &out,
            GenerateOptions::new(GenerateMode::Create, DependencySource::Path),
            ModelFormat::Sql,
            ModelOrm::Toasty,
        )
        .expect("generate");

        let ext_path = out.join("src/model/user_ext.rs");
        fs::write(&ext_path, "// custom extension\n").expect("write custom ext");

        generate_model_project(
            source,
            &out,
            GenerateOptions::new(GenerateMode::Update, DependencySource::Path),
            ModelFormat::Sql,
            ModelOrm::Toasty,
        )
        .expect("update generate");

        assert_eq!(
            fs::read_to_string(&ext_path).expect("read custom ext"),
            "// custom extension\n"
        );

        let switched = resolve_model_orm(&out, GenerateMode::Update, Some(ModelOrm::SeaOrm), true)
            .expect("confirm explicit ORM switch");
        generate_model_project(
            source,
            &out,
            GenerateOptions::new(GenerateMode::Update, DependencySource::Path),
            ModelFormat::Sql,
            switched,
        )
        .expect("switch ORM");
        assert_eq!(
            fs::read_to_string(ext_path).expect("read custom ext after switch"),
            "// custom extension\n"
        );
        assert!(fs::read_to_string(out.join("src/model/mod.rs"))
            .expect("read model marker")
            .contains("// @roze-model-orm: sea-orm"));
    }

    #[test]
    fn model_generator_extensions_transform_graph_and_obey_file_ownership() {
        struct TestExtension;

        impl ModelGeneratorExtension for TestExtension {
            fn name(&self) -> &'static str {
                "test-extension"
            }

            fn transform(&self, graph: &mut ModelGenerationGraph) -> anyhow::Result<()> {
                graph.models[0].annotations.push(ModelAnnotation {
                    name: "roze.Audit".to_string(),
                    expression: "roze.Audit(\"v1\")".to_string(),
                });
                Ok(())
            }

            fn generate(
                &self,
                graph: &ModelGenerationGraph,
            ) -> anyhow::Result<Vec<ModelExtensionFile>> {
                assert_eq!(graph.orm, ModelOrm::Toasty);
                assert!(graph.canonical_ent.contains("roze.Audit(\"v1\")"));
                Ok(vec![
                    ModelExtensionFile {
                        relative_path: PathBuf::from("src/model/audit_generated.rs"),
                        contents: format!("// {} models\n", graph.models.len()),
                        ownership: ExtensionFileOwnership::Generated,
                    },
                    ModelExtensionFile {
                        relative_path: PathBuf::from("src/model/audit_policy.rs"),
                        contents: "// application policy\n".to_string(),
                        ownership: ExtensionFileOwnership::Application,
                    },
                ])
            }
        }

        let unique = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("time")
            .as_nanos();
        let out = std::env::temp_dir().join(format!("rozectl-model-api-out-{unique}"));
        write_minimal_main(&out);
        let source = r#"
            entity User {
                table "users"
                field Int64("id").Primary() {
                    Annotations(entgql.OrderField("ID"))
                }
                index Fields("id") {
                    Annotations(entsql.Desc("user ids"))
                }
            }
        "#;
        let extension = TestExtension;

        generate_model_project_with_extensions(
            source,
            &out,
            GenerateOptions::new(GenerateMode::Create, DependencySource::Path),
            ModelFormat::Ent,
            ModelOrm::Toasty,
            &[&extension],
        )
        .expect("generate with extension");

        let canonical = fs::read_to_string(out.join("src/model/schema.ent")).expect("schema");
        assert!(canonical.contains("roze.Audit(\"v1\")"));
        assert!(canonical.contains("entgql.OrderField(\"ID\")"));
        assert!(canonical.contains("entsql.Desc(\"user ids\")"));
        assert_eq!(
            fs::read_to_string(out.join("src/model/audit_generated.rs")).expect("generated"),
            "// 1 models\n"
        );

        let application_file = out.join("src/model/audit_policy.rs");
        fs::write(&application_file, "// user changed policy\n").expect("edit policy");
        generate_model_project_with_extensions(
            source,
            &out,
            GenerateOptions::new(GenerateMode::Update, DependencySource::Path),
            ModelFormat::Ent,
            ModelOrm::Toasty,
            &[&extension],
        )
        .expect("update with extension");
        assert_eq!(
            fs::read_to_string(application_file).expect("application file"),
            "// user changed policy\n"
        );
    }

    #[test]
    fn model_generator_extensions_cannot_escape_or_replace_core_artifacts() {
        struct UnsafeExtension(PathBuf);

        impl ModelGeneratorExtension for UnsafeExtension {
            fn name(&self) -> &'static str {
                "unsafe-extension"
            }

            fn generate(
                &self,
                _graph: &ModelGenerationGraph,
            ) -> anyhow::Result<Vec<ModelExtensionFile>> {
                Ok(vec![ModelExtensionFile {
                    relative_path: self.0.clone(),
                    contents: "unsafe".to_string(),
                    ownership: ExtensionFileOwnership::Generated,
                }])
            }
        }

        let source = r#"
            entity User {
                field Int64("id").Primary() {
                }
            }
        "#;
        for relative_path in [
            PathBuf::from("../escape.rs"),
            PathBuf::from("src/model/client.rs"),
        ] {
            let unique = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .expect("time")
                .as_nanos();
            let out = std::env::temp_dir().join(format!("rozectl-model-unsafe-{unique}"));
            write_minimal_main(&out);
            let extension = UnsafeExtension(relative_path);
            let error = generate_model_project_with_extensions(
                source,
                &out,
                GenerateOptions::new(GenerateMode::Create, DependencySource::Path),
                ModelFormat::Ent,
                ModelOrm::SeaOrm,
                &[&extension],
            )
            .expect_err("unsafe extension output must fail");
            assert!(error.to_string().contains("extension `unsafe-extension`"));
        }
    }

    #[test]
    fn model_update_removes_only_marked_stale_generated_files() {
        let unique = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("time")
            .as_nanos();
        let out = std::env::temp_dir().join(format!("rozectl-model-stale-out-{unique}"));
        write_minimal_main(&out);

        let source = r#"
            CREATE TABLE users (
                id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
                name VARCHAR(255) NOT NULL
            );
            "#;

        generate_model_project(
            source,
            &out,
            GenerateOptions::new(GenerateMode::Create, DependencySource::Path),
            ModelFormat::Sql,
            ModelOrm::Toasty,
        )
        .expect("generate");

        let model_dir = out.join("src/model");
        fs::write(
            model_dir.join("old_order.rs"),
            format!("{MODEL_GENERATED_MARKER}\n"),
        )
        .expect("stale model");
        fs::write(
            model_dir.join("old_order_fields.rs"),
            format!("{MODEL_GENERATED_MARKER}\n"),
        )
        .expect("stale fields");
        fs::write(model_dir.join("manual.rs"), "// custom file\n").expect("manual file");
        fs::write(
            model_dir.join("old_order_ext.rs"),
            format!("{MODEL_GENERATED_MARKER}\n// should stay\n"),
        )
        .expect("stale ext");

        generate_model_project(
            source,
            &out,
            GenerateOptions::new(GenerateMode::Update, DependencySource::Path),
            ModelFormat::Sql,
            ModelOrm::Toasty,
        )
        .expect("update generate");

        assert!(!model_dir.join("old_order.rs").exists());
        assert!(!model_dir.join("old_order_fields.rs").exists());
        assert!(model_dir.join("manual.rs").exists());
        assert!(model_dir.join("old_order_ext.rs").exists());
    }

