    #[test]
    fn renders_mongo_repository_with_cache_keys() {
        let source = r#"
        model User {
            table: users
            primary: id
            cache: true
            cache_key: id,username
            cache_prefix: account
            cache_ttl_secs: 120
            negative_cache_ttl_secs: 10
            field id ObjectId
            field username String
            field display_name Option<String>
        }
        "#;
        let models = parse_models_with_format(source, ModelFormat::Mongo).expect("parse");
        assert_eq!(models[0].cache_keys, vec!["id", "username"]);

        let rendered = render_mongo_model_module(&models[0]);
        assert!(rendered.contains("roze_mongo::bson"));
        assert!(rendered.contains("#[serde(rename = \"_id\")]"));
        assert!(rendered.contains("pub async fn find_by_username"));
        assert!(rendered.contains("pub async fn cached_find_by_username"));
        assert!(rendered.contains("pub fn fixture(index: u64) -> Self"));
        assert!(rendered.contains("pub async fn seed_fixtures(&self, count: u64)"));
        assert!(rendered.contains("Self::filter_by(\"_id\", &id)?"));
        assert!(rendered.contains("roze_cache::model_cache_key(\"account\", field, value)"));
        assert!(rendered.contains("cache.del(&self.cache_key(\"username\", &model.username))"));
    }

    #[test]
    fn infers_mongo_model_from_sample_documents() {
        let documents = vec![
            doc! {
                "_id": Bson::ObjectId(mongodb::bson::oid::ObjectId::new()),
                "username": "alice",
                "score": 7_i32,
                "active": true,
                "tags": Bson::Array(vec![Bson::String("vip".to_string())]),
                "display-name": "Alice",
            },
            doc! {
                "_id": Bson::ObjectId(mongodb::bson::oid::ObjectId::new()),
                "username": "bob",
                "score": 9_i64,
                "display-name": "Bob",
            },
        ];

        let model = model_from_mongo_documents(
            "users",
            &documents,
            vec![
                ModelIndex {
                    name: "display_name_1".to_string(),
                    fields: vec!["display_name".to_string()],
                    unique: true,
                    annotations: Vec::new(),
                },
                ModelIndex {
                    name: "username_display_name_1".to_string(),
                    fields: vec!["username".to_string(), "display_name".to_string()],
                    unique: true,
                    annotations: Vec::new(),
                },
            ],
        );
        assert_eq!(model.name, "Users");
        assert_eq!(model.table, "users");
        assert_eq!(model.primary, "id");
        assert_eq!(
            model.indexes,
            vec![
                ModelIndex {
                    name: "display_name_1".to_string(),
                    fields: vec!["display_name".to_string()],
                    unique: true,
                    annotations: Vec::new(),
                },
                ModelIndex {
                    name: "username_display_name_1".to_string(),
                    fields: vec!["username".to_string(), "display_name".to_string()],
                    unique: true,
                    annotations: Vec::new(),
                }
            ]
        );
        assert_eq!(model.cache_keys, vec!["display_name"]);
        let graph = ModelGenerationGraph {
            canonical_ent: render_ent_schema(std::slice::from_ref(&model)),
            models: vec![model.clone()],
            orm: ModelOrm::SeaOrm,
        };
        let requirements = model_project_requirements(&graph, ModelBackend::MongoDb);
        assert_eq!(requirements.backend, ModelBackend::MongoDb);
        assert!(requirements.dependency("roze-mongo").is_some());
        assert!(requirements.requires(RuntimeCapability::MongoConnection));
        assert!(requirements.requires(RuntimeCapability::HealthRegistration));
        assert!(requirements.requires(RuntimeCapability::ModelContextHook));
        assert_eq!(
            model
                .fields
                .iter()
                .find(|field| field.name == "id")
                .map(|field| field.ty.as_str()),
            Some("ObjectId")
        );
        assert_eq!(
            model
                .fields
                .iter()
                .find(|field| field.name == "score")
                .map(|field| field.ty.as_str()),
            Some("i64")
        );
        assert_eq!(
            model
                .fields
                .iter()
                .find(|field| field.name == "active")
                .map(|field| field.ty.as_str()),
            Some("Option<bool>")
        );
        assert_eq!(
            model
                .fields
                .iter()
                .find(|field| field.name == "tags")
                .map(|field| field.ty.as_str()),
            Some("Option<Vec<String>>")
        );
        assert_eq!(
            model
                .fields
                .iter()
                .find(|field| field.name == "display_name")
                .and_then(|field| field.source_name.as_deref()),
            Some("display-name")
        );

        let rendered = render_mongo_model_module(&model);
        assert!(rendered.contains("#[serde(rename = \"display-name\")]"));
        assert!(rendered.contains("Self::filter_by(\"display-name\", &display_name)?"));
        assert!(rendered.contains("pub async fn find_by_username_and_display_name"));
        assert!(
            rendered.contains("filter.insert(\"display-name\", bson::to_bson(&display_name)?);")
        );
    }

