pub fn secure_user_query<'a>(
    db: &'a mut dyn toasty::Executor,
    rules: Vec<std::sync::Arc<dyn roze_orm::Policy<crate::model::UserQuery<'a>, Error = toasty::Error> + 'a>>,
) -> crate::model::UserQuery<'a> {
    UserRepository::query(db)
        .mixin(IdentityMixin)
        .policy(rules, || toasty::Error::invalid_record_count("privacy denied"))
}

pub async fn traverse_groups_with_interceptor<'a, I>(
    user: &User,
    db: &'a mut dyn toasty::Executor,
    interceptor: I,
) -> toasty::Result<()>
where
    I: roze_orm::OperationMiddleware<GroupQuery<'a>, Vec<Group>, toasty::Error> + 'a,
{
    let _groups = user
        .traverse_groups(db)
        .await?
        .around(interceptor)
        .all()
        .await?;
    Ok(())
}

pub async fn load_three_levels(db: &mut dyn toasty::Executor) -> toasty::Result<()> {
    let _loaded = UserRepository::query(db)
        .all_with_groups_nested(|groups_query| async move {
            groups_query
                .all_with_users_nested(|users_query| async move {
                    users_query
                        .all_with_orders_nested(|orders_query| async move {
                            orders_query.all().await
                        })
                        .await
                })
                .await
        })
        .await?;
    let _combined = SessionRepository::query(db)
        .all_with_account_and_owner()
        .await?;
    Ok(())
}

