    #[tokio::test]
    async fn sqlite_model_parity_database_evidence() {
        let pool = sqlx::sqlite::SqlitePoolOptions::new()
            .max_connections(1)
            .connect("sqlite::memory:")
            .await
            .expect("sqlite");
        sqlx::query("CREATE TABLE roze_model_parity (id BIGINT PRIMARY KEY, bucket TEXT NOT NULL, score BIGINT NULL)")
            .execute(&pool)
            .await
            .expect("create");
        for (id, bucket, score) in [
            (1_i64, "a", Some(10_i64)),
            (2, "a", None),
            (3, "b", Some(7)),
        ] {
            sqlx::query("INSERT INTO roze_model_parity (id, bucket, score) VALUES (?, ?, ?)")
                .bind(id)
                .bind(bucket)
                .bind(score)
                .execute(&pool)
                .await
                .expect("insert");
        }
        sqlx::query("UPDATE roze_model_parity SET score = score + ? WHERE bucket = ?")
            .bind(5_i64)
            .bind("a")
            .execute(&pool)
            .await
            .expect("atomic update");
        let rows = sqlx::query_as::<_, ModelParityRow>(
            "SELECT bucket, COUNT(*), CAST(SUM(score) AS INTEGER), CAST(AVG(score) AS REAL), MIN(score), MAX(score) FROM roze_model_parity GROUP BY bucket ORDER BY bucket",
        )
        .fetch_all(&pool)
        .await
        .expect("group");
        assert_model_parity_rows(&rows);
    }

