    fn run_generated_toasty_runtime(url: &str, backend: &str) {
        let out = write_generated_toasty_runtime_fixture(backend);
        let output = Command::new("cargo")
            .arg("run")
            .arg("--offline")
            .arg("--quiet")
            .current_dir(&out)
            .env("TEST_DATABASE_URL", url)
            .output()
            .expect("run generated Toasty runtime fixture");
        if !output.status.success() {
            panic!(
                "generated Toasty {backend} runtime failed in {}\nstdout:\n{}\nstderr:\n{}",
                out.display(),
                String::from_utf8_lossy(&output.stdout),
                String::from_utf8_lossy(&output.stderr)
            );
        }
    }

