    fn write_generated_toasty_runtime_fixture(backend: &str) -> PathBuf {
        let out = temp_model_output(&format!("toasty-{backend}-runtime"));
        write_generated_crate_manifest(
            &out,
            r#"[package]
name = "generated-toasty-runtime-evidence"
edition = "2021"
version = "0.0.0"

[dependencies]
serde = { version = "1", features = ["derive"] }
toasty = { version = "0.7", default-features = false, features = ["postgresql", "mysql", "serde"] }
tokio = { version = "1", features = ["macros", "rt-multi-thread"] }
"#,
        );
        add_local_roze_orm_dependency(&out);
        fs::write(out.join("src/main.rs"), "fn main() {}\n").expect("placeholder main");
        generate_model_project(
            r#"
            entity Counter {
                table "roze_toasty_parity"
                field String("id").Primary() {
                }
                field String("bucket") {
                }
                field Int64("score").Optional() {
                }
            }
            "#,
            &out,
            GenerateOptions::new(GenerateMode::Create, DependencySource::Git),
            ModelFormat::Ent,
            ModelOrm::Toasty,
        )
        .expect("generate Toasty runtime fixture");
        fs::write(
            out.join("src/main.rs"),
            r#"mod model;

use model::{counter, Counter, CounterMutationHooks, CounterRepository, CounterUpdateMany};
use std::sync::{
    atomic::{AtomicUsize, Ordering},
    Arc,
};

struct Allow;

impl<C> roze_orm::Policy<C> for Allow {
    type Error = toasty::Error;

    fn evaluate(&self, _context: &C) -> Result<roze_orm::PolicyDecision, Self::Error> {
        Ok(roze_orm::PolicyDecision::Allow)
    }
}

struct CountingAtomicHook(Arc<AtomicUsize>);

impl<'db> roze_orm::OperationMiddleware<CounterUpdateMany<'db>, (), toasty::Error>
    for CountingAtomicHook
{
    fn call<'a>(
        &'a self,
        mutation: CounterUpdateMany<'db>,
        next: roze_orm::OperationNext<'a, CounterUpdateMany<'db>, (), toasty::Error>,
    ) -> roze_orm::OperationFuture<'a, (), toasty::Error>
    where
        CounterUpdateMany<'db>: 'a,
        (): 'a,
        toasty::Error: 'a,
    {
        let calls = self.0.clone();
        Box::pin(async move {
            calls.fetch_add(1, Ordering::SeqCst);
            let result = next.run(mutation).await;
            calls.fetch_add(1, Ordering::SeqCst);
            result
        })
    }
}

struct ApplicationHooks(Arc<AtomicUsize>);

impl CounterMutationHooks for ApplicationHooks {
    fn update_many<'db>(
        &self,
        mutation: CounterUpdateMany<'db>,
    ) -> CounterUpdateMany<'db> {
        mutation.atomic_hook(CountingAtomicHook(self.0.clone()))
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let url = std::env::var("TEST_DATABASE_URL")?;
    let mut db = toasty::Db::builder()
        .models(toasty::models!(Counter))
        .connect(&url)
        .await?;
    toasty::sql::statement("DROP TABLE IF EXISTS roze_toasty_parity")
        .exec(&mut db)
        .await?;
    toasty::sql::statement("CREATE TABLE roze_toasty_parity (id VARCHAR(64) PRIMARY KEY, bucket VARCHAR(32) NOT NULL, score BIGINT NULL)")
        .exec(&mut db)
        .await?;

    toasty::sql::statement("INSERT INTO roze_toasty_parity (id, bucket, score) VALUES ('1', 'a', 10), ('2', 'a', NULL), ('3', 'b', 7)")
        .exec(&mut db)
        .await?;

    CounterRepository::query(&mut db)
        .where_(counter::bucket_contains("a"))
        .add_score(5)
        .await?;
    let hook_calls = Arc::new(AtomicUsize::new(0));
    let hooks = ApplicationHooks(hook_calls.clone());
    let mutation = hooks
        .update_many(CounterRepository::update_many(&mut db))
        .where_(counter::and(vec![
            counter::bucket_eq("b".to_string()),
            counter::score_is_not_null(),
        ]));
    let rules: Vec<Arc<dyn roze_orm::Policy<CounterUpdateMany<'_>, Error = toasty::Error> + '_>> =
        vec![Arc::new(Allow)];
    mutation
        .policy(rules, || toasty::Error::invalid_record_count("privacy denied"))
        .add_score(2)
        .await?;
    assert_eq!(hook_calls.load(Ordering::SeqCst), 2);

    let rows = CounterRepository::query(&mut db).order_by_id_asc().all().await?;
    assert_eq!(rows.iter().map(|row| row.score).collect::<Vec<_>>(), vec![Some(15), None, Some(9)]);
    let mut sums = CounterRepository::query(&mut db)
        .order_by_id_asc()
        .limit(2)
        .sum_score_by_bucket()
        .await?;
    sums.sort_by(|left, right| left.0.cmp(&right.0));
    assert_eq!(sums, vec![("a".to_string(), 15)]);
    let mut counts = CounterRepository::query(&mut db)
        .where_(counter::bucket_ne("z".to_string()))
        .count_by_bucket()
        .await?;
    counts.sort_by(|left, right| left.0.cmp(&right.0));
    assert_eq!(counts, vec![("a".to_string(), 2), ("b".to_string(), 1)]);

    toasty::sql::statement("DROP TABLE roze_toasty_parity")
        .exec(&mut db)
        .await?;
    Ok(())
}
"#,
        )
        .expect("runtime main");
        out
    }

    type ModelParityRow = (
        String,
        i64,
        Option<i64>,
        Option<f64>,
        Option<i64>,
        Option<i64>,
    );

    fn assert_model_parity_rows(rows: &[ModelParityRow]) {
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0].0, "a");
        assert_eq!(rows[0].1, 2);
        assert_eq!(rows[0].2, Some(15));
        assert_eq!(rows[0].3, Some(15.0));
        assert_eq!(rows[0].4, Some(15));
        assert_eq!(rows[0].5, Some(15));
        assert_eq!(rows[1].0, "b");
        assert_eq!(rows[1].1, 1);
        assert_eq!(rows[1].2, Some(7));
        assert_eq!(rows[1].3, Some(7.0));
        assert_eq!(rows[1].4, Some(7));
        assert_eq!(rows[1].5, Some(7));
    }

